#!/usr/bin/env python3
# =====================================================================
#  apply_ic2_hedge_flat.py  —  fence IC2_HEDGE_FLAT_20261117   (on v11.9.2)
#
#  IC_V2 (Icarus): when every short (L1/L2) and every ·ADJ leg is closed by
#  SL/TP/MTC and no adjustment is waiting to open, the L3/L4 hedge BUYS are
#  sold straight away (exit reason HEDGE_FLAT) instead of riding alone to the
#  expiry-day close or to the next morning. Backtest AND Paper/Live.
#
#   Paper/Live  setting hedge_close_when_flat — Settings → IC_V2 → Execution →
#               "Close Hedges When Flat", default ON (absent = ON for the carry
#               model; IC_V1 / EOD stays off). Checked every engine iteration
#               (~4 s): market hours 09:15–15:30 only, never on a carried book
#               (09:16 morning close owns that), STRICT sell — a failed order
#               leaves the wing open and is retried.
#   Backtest    config key hedge_close_when_flat (form tick-box, default ON;
#               runner treats an ABSENT key as OFF so older saved runs
#               reproduce). Wings sell at the OPEN of the minute after the last
#               other leg leaves. Run chip, Compare row, Queue tag, sweep axis
#               "Close hedges when flat (0/1)".
#
#   backend/app/backtest/ic/ic_v1_engine.py        hedge_close_when_flat
#   backend/app/backtest/ic/backtest_ic_runner.py  key, diag, synthetic re-mark
#   backend/app/engine/ic/ic_group_manager.py      _close_orphan_hedges()
#   backend/app/config/strategy_loader.py          IC_V2 default True
#   backend/app/backtest/ic/test_ic2_hedge_flat.py NEW  TC-ICHF-0101…0114
#   backend/app/engine/ic/test_ic_hedge_flat.py    NEW  TC-ICHF-0001…0008
#   frontend/src/pages/Settings.jsx, Backtest.jsx,
#   frontend/src/pages/backtest/RunComparison.jsx, BacktestQueue.jsx, SweepBuilder.jsx
#
#  Run ONLY this script, outside market hours:
#     cd ~/dev/scalp-app && python3 apply_ic2_hedge_flat.py
#  Options: --repo PATH  --skip-tests  --allow-dirty  --rollback
#  Then: ./desktop/build-scalp.sh both, restart the app.
# =====================================================================
import base64, hashlib, json, os, py_compile, shutil, subprocess, sys, tempfile, zlib

FENCE = "IC2_HEDGE_FLAT_20261117"
ITEMS = json.loads(r'''[{"path": "backend/app/backtest/ic/ic_v1_engine.py", "orig": "b19a72e0500e0d2d86e6db6f578b3e150d2e5021418060e5d877ca4ebc1336f2", "new": "e6f624c2a0c5e95d137bba23936614dc0a55468073a75cdec695a73f5dda820c", "blob": ""}, {"path": "backend/app/backtest/ic/backtest_ic_runner.py", "orig": "b44fe21228470d35d63bb6993cf723b4243f7fa828ab89a9ed8a67c45a6a7909", "new": "5576e026fc3082190e79b00485df3e15a4aac11c4e0a46da4dc1d82ae3b6dfed", "blob": ""}, {"path": "backend/app/engine/ic/ic_group_manager.py", "orig": "bc1dee0df89a20977687d5916165fc7da6693411aef98bf436e3084f6319fe7e", "new": "81b2da5bb29e1292010877dbbe7cc072a2b762d439eb64691f2ac3006ea9d120", "blob": ""}, {"path": "backend/app/config/strategy_loader.py", "orig": "323a111358298e1972f066194708cc27bc28dde0481c6452bf0aec0bc96f3746", "new": "e1c672cc2e34b87ffb4cacd06593b6ba8d9d2d34b4b7044764452e944d01b12b", "blob": ""}, {"path": "frontend/src/pages/Backtest.jsx", "orig": "11841dc1748ba38713286743cf91fb73b691d1fa23836cc49caadf2a2f201cbd", "new": "2c22468b217e260a3550037292e7ba318132e32f2902bf9cfe113f4b4baba88f", "blob": ""}, {"path": "frontend/src/pages/Settings.jsx", "orig": "497bb1f65145a8c29cf7816f0c7cf996066a9c64b7cd046afedc9a661f6d69bf", "new": "323ea5d875ffb98fd63dd5426c77150acc2ae124df9bd9226e06accd9b73541a", "blob": ""}, {"path": "frontend/src/pages/backtest/RunComparison.jsx", "orig": "6ebc1684830a09fb3f9872c01e08b987ef18d151c218b2e3d7e20190d1e68230", "new": "4767f1eb27e547b5da0e67af418668be60efe91f3257a491f553dc806fb33d6f", "blob": ""}, {"path": "frontend/src/pages/backtest/BacktestQueue.jsx", "orig": "5cc2077ebadc2707de98d85443d38731cd7c87874c6ef986bbee8ece5feab3cd", "new": "3350d8d371358d04307306fa8780b33293551b459c46043dddb48eb38635b0fb", "blob": ""}, {"path": "frontend/src/pages/backtest/SweepBuilder.jsx", "orig": "030a34868a5d4b49ec727175eaa56322c5e4d708605933e71b5b089d5d2f5b6a", "new": "fa5be7c0c587c54a8db97f72be7eac8b71e7e68129b40e7d674a81a889fecf26", "blob": ""}, {"path": "backend/app/backtest/ic/test_ic2_hedge_flat.py", "orig": null, "new": "c87cfdff09f3fc278088269535abca45b275f28ae67766ea9e8386b73070e189", "blob": ""}, {"path": "backend/app/engine/ic/test_ic_hedge_flat.py", "orig": null, "new": "d2e161770c7358b0aa5374f7691b9b790bd23ff6d1e6ff60df0d1fccfe9a77c7", "blob": ""}]''')
BUILD_COPIES = {"backend/": "desktop/src-tauri/backend/", "frontend/": "desktop/src-tauri/frontend/"}
TESTS = ["app/backtest/ic/test_ic2_hedge_flat.py", "app/engine/ic/test_ic_hedge_flat.py",
         "app/backtest/ic/test_ic2_expiry_next.py", "app/backtest/ic/test_ic_adjust_fill.py",
         "app/backtest/ic/test_ic2_short_tp_skip_exp.py"]


def sha(b):
    return hashlib.sha256(b).hexdigest()


def say(m):
    print(m, flush=True)


def die(m):
    say(f"\n✗ ABORTED — {m}\n  Nothing was changed.")
    sys.exit(1)


args = sys.argv[1:]
repo = os.path.abspath(os.path.expanduser(args[args.index("--repo") + 1])) if "--repo" in args else os.getcwd()
if not os.path.isdir(os.path.join(repo, "backend", "app")):
    alt = os.path.expanduser("~/dev/scalp-app")
    if os.path.isdir(os.path.join(alt, "backend", "app")):
        repo = alt
    else:
        die(f"{repo} is not the scalp-app repo (no backend/app) — pass --repo PATH")
say(f"repo: {repo}\nfence: {FENCE}")

# ── prerequisite: the IC_V2 runner of v11.9.2 (next-week expiry option present)
if "--rollback" not in args:
    _pf = os.path.join(repo, "backend", "app", "backtest", "ic", "backtest_ic_runner.py")
    if not os.path.exists(_pf) or "IC2_EXPIRY_NEXT_20261103" not in open(_pf, encoding="utf-8").read():
        die("backtest_ic_runner.py lacks IC2_EXPIRY_NEXT_20261103 — pull main (v11.9.2) first")


def targets():
    """(item, absolute path, is_build_copy)"""
    out = []
    for it in ITEMS:
        out.append((it, os.path.join(repo, it["path"]), False))
        for a, b in BUILD_COPIES.items():
            if it["path"].startswith(a):
                p = os.path.join(repo, b + it["path"][len(a):])
                if os.path.isdir(os.path.dirname(p)):
                    out.append((it, p, True))
    return out


# ── rollback mode ────────────────────────────────────────────────────
if "--rollback" in args:
    later = []
    for it, p, build in targets():
        if build or not os.path.exists(p) or not os.path.exists(p + ".bak-" + FENCE):
            continue
        with open(p, "rb") as f:
            if sha(f.read()) != it["new"]:
                later.append(os.path.relpath(p, repo))
    if later:
        die("cannot roll back — changed again after this script (by a later fix or a local edit): "
            + ", ".join(later) + ". Roll the later fixes back first, newest first. Nothing was changed.")
    n = 0
    for it, p, _ in targets():
        bak = p + ".bak-" + FENCE
        if os.path.exists(bak):
            shutil.copy2(bak, p)
            os.remove(bak)
            n += 1
        elif it["orig"] is None and os.path.exists(p):
            with open(p, "rb") as f:
                if sha(f.read()) == it["new"]:
                    os.remove(p)
                    n += 1
    say(f"rolled back {n} file(s)")
    sys.exit(0)

# ── 1. state of every target ─────────────────────────────────────────
plan, done, skipped, later = [], 0, [], []
_applied = False                         # this script's marker is in the tree → it was applied
for it, p, build in targets():
    if not build and os.path.exists(p):
        with open(p, "rb") as f:
            if FENCE.encode() in f.read():
                _applied = True
for it, p, build in targets():
    cur = open(p, "rb").read() if os.path.exists(p) else None
    cs = sha(cur) if cur is not None else None
    rel = os.path.relpath(p, repo)
    if cs == it["new"]:
        done += 1
        continue
    if cs == it["orig"]:
        plan.append((it, p, cur, build))
        continue
    if build:
        skipped.append(rel)              # a stale build copy — the build re-syncs it
        continue
    if cur is None:
        die(f"{rel} is missing")
    if _applied:
        later.append(rel)                # applied, then changed by a later fix
        continue
    die(f"{rel} differs from GitHub main and from the patched version — local edits? "
        f"(commit/stash them or pull main, then re-run)")
if not plan:
    say(f"✓ already applied ({done} file(s) carry {FENCE}"
        + (f"; {len(later)} changed again by later fixes" if later else "") + ") — nothing to do")
    sys.exit(0)
if later:
    die("partly applied: " + ", ".join(later) + " changed after this script while other files are "
        "not patched — check the tree (git status) before going on. Nothing was changed.")

# ── 2. git status: an uncommitted change on a target is a stop sign ──
if "--allow-dirty" not in args:
    try:
        rels = [os.path.relpath(p, repo) for _, p, _, b in plan if not b]
        st = subprocess.run(["git", "status", "--porcelain", "--"] + rels, cwd=repo,
                            capture_output=True, text=True, timeout=30).stdout
        dirty = [l for l in st.splitlines() if l[:2].strip() and not l.startswith("??")]
        # a planned file was just proven byte-identical to GitHub main (sha == orig): only other drift stops us.
        _ok = {os.path.relpath(p, repo) for it, p, _c, b in plan if not b and it["orig"] is not None}
        dirty = [l for l in dirty if l[3:].strip() not in _ok]
        if dirty:
            die("uncommitted changes on target files:\n  " + "\n  ".join(dirty) + "\n  (re-run with --allow-dirty to override)")
    except FileNotFoundError:
        say("  (git not found — skipping the status check)")

# ── 3. decode + compile every payload before writing anything ───────
tmp = tempfile.mkdtemp(prefix="ic2_hedge_flat_")
blobs = {}
for it in ITEMS:
    b = zlib.decompress(base64.b64decode(it["blob"]))
    if sha(b) != it["new"]:
        die(f"payload for {it['path']} is corrupt")
    blobs[it["path"]] = b
    if it["path"].endswith(".py"):
        f = os.path.join(tmp, os.path.basename(it["path"]))
        open(f, "wb").write(b)
        try:
            py_compile.compile(f, doraise=True)
        except py_compile.PyCompileError as e:
            die(f"payload {it['path']} does not compile: {e}")
say(f"payloads verified and compiled ({len(ITEMS)} files)")

# ── 4. write, all or nothing ─────────────────────────────────────────
written = []


def restore():
    for p, old in reversed(written):
        try:
            if old is None:
                os.remove(p)
            else:
                open(p, "wb").write(old)
            bak = p + ".bak-" + FENCE
            if os.path.exists(bak):
                os.remove(bak)
        except Exception as e:
            say(f"  !! could not restore {p}: {e}")


try:
    for it, p, cur, build in plan:
        if cur is not None:
            open(p + ".bak-" + FENCE, "wb").write(cur)
        t = p + ".tmp-" + FENCE
        os.makedirs(os.path.dirname(p), exist_ok=True)   # a new file may need a new folder
        open(t, "wb").write(blobs[it["path"]])
        os.replace(t, p)
        written.append((p, cur))
        say(f"  wrote {os.path.relpath(p, repo)}{'  (build copy)' if build else ''}")
except Exception as e:
    restore()
    die(f"write failed ({e!r}) — everything restored")
for s_ in skipped:
    say(f"  skipped stale build copy {s_} (the next build re-syncs it)")

# ── 5. tests ─────────────────────────────────────────────────────────
backend = os.path.join(repo, "backend")
py = next((c for c in (os.path.join(backend, "venv", "bin", "python"), os.path.join(backend, ".venv", "bin", "python"),
                       os.path.join(repo, "venv", "bin", "python"), os.path.join(repo, ".venv", "bin", "python"))
           if os.path.exists(c)), sys.executable)
if "--skip-tests" in args:
    say("tests skipped (--skip-tests)")
else:
    say(f"running tests with {py}")
    env = dict(os.environ, PYTHONPATH=backend, SCALP_TEST_MODE="1")
    failed, envmiss = [], []
    for t in TESTS:
        if not os.path.exists(os.path.join(backend, t)):
            continue
        try:
            r = subprocess.run([py, t], cwd=backend, env=env, capture_output=True, text=True, timeout=900)
            outp = (r.stdout or "") + (r.stderr or "")
        except subprocess.TimeoutExpired:
            r, outp = None, "timeout"
        last = (outp.strip().splitlines() or [""])[-1]
        if r is not None and r.returncode == 0:
            say(f"  ✓ {t}  {last}")
        elif "ModuleNotFoundError" in outp and "No module named 'app" not in outp:
            envmiss.append(t)
            say(f"  ? {t}  could not run here: {last}")
        else:
            failed.append(t)
            say(f"  ✗ {t}\n" + "\n".join("      " + l for l in outp.strip().splitlines()[-25:]))
    if failed:
        restore()
        die("tests failed: " + ", ".join(failed) + " — every file restored")
    if envmiss:
        say("  note: some suites need the backend's Python packages; re-run them with that Python")

# ── 5b. JSX parse gate (esbuild from frontend/node_modules, if installed) ──
_esb = os.path.join(repo, "frontend", "node_modules", ".bin", "esbuild")
if os.path.exists(_esb) and "--skip-tests" not in args:
    bad = []
    for it in ITEMS:
        if it["path"].startswith("frontend/src/") and it["path"].endswith((".jsx", ".js")):
            r = subprocess.run([_esb, os.path.join(repo, it["path"]), "--loader:.js=jsx", "--loader:.jsx=jsx",
                                "--log-level=error"], capture_output=True, text=True)
            if r.returncode != 0:
                bad.append(it["path"] + ": " + (r.stderr or "").strip()[:300])
    if bad:
        restore()
        die("JSX does not parse — every file restored:\n  " + "\n  ".join(bad))
    say("  ✓ esbuild parsed the changed frontend files")
else:
    say("  (esbuild not installed — the build will compile the frontend)")

shutil.rmtree(tmp, ignore_errors=True)
say(f"\n✓ {FENCE} applied ({len(written)} file(s)). Next: ./desktop/build-scalp.sh both, then restart the app.")
say("  Undo: python3 apply_ic2_hedge_flat.py --rollback")
